struct Requests final:a::Requests {a::RecoverySession* recovery{};rpc::CookieCredentials credentials;rpc::Transport transport{credentials};RefreshService refresh{[this](const auto& r,std::stop_token stop){return FetchRefresh(transport,r,stop);}};ConnectionService connection{[this](const auto& c,std::stop_token stop){return ProbeCapabilities(transport,c,stop);},[this](bool b){refresh.SetOffline(b,RefreshMonotonicMs());}};ConnectionService* Connection() override{return &connection;}RefreshService* Refresh() override{return &refresh;}a::RecoverySession* Recovery() override{return recovery;}a::HostObservations Observe() const override{return a::ConnectionObservations(connection,refresh);}a::Availability CanSubmit(const a::Request& r) const override{return {r.command==a::Command::Refresh,"Read-only refresh only"};}a::Receipt Submit(const a::Request& r) override{if(r.command==a::Command::Refresh)return {refresh.RequestNow(RefreshMonotonicMs()),"Read-only refresh"};throw std::runtime_error("unexpected host mutation");}};
struct Observer final:platform::NativeObserver {
    Requests requests;sh::State state;sh::Facts facts;std::filesystem::path out;Display* display{};void* xtst{};int(*motion)(Display*,int,int,int,unsigned long){};int(*button)(Display*,unsigned int,Bool,unsigned long){};int(*key)(Display*,unsigned int,Bool,unsigned long){};int checks{},stage{},base{};int64_t expected{};bool done{},cleaned{};std::set<std::string> selected;std::vector<std::string> keys;uint64_t draft{};std::chrono::steady_clock::time_point started=std::chrono::steady_clock::now();
    void Check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
    bool CaptureFramebuffer() const override{return true;}
    void Idle(platform::NativeHost&,const platform::NativeFrame&) override{if(std::chrono::steady_clock::now()-started>std::chrono::seconds(25))throw std::runtime_error("native coin-control deadline stage="+std::to_string(stage)+" history_error="+rpc::ErrorName(requests.refresh.View().errors[2]));}
    void Click(platform::NativeHost& host,const ui::components::ItemFacts& item,bool down,unsigned native_button=1){const auto& r=item.rect;if(!(item.visible && !item.disabled && r[0]>=0 && r[1]>=0 && r[2]<=960 && r[3]<=640))std::cerr<<"unreachable stage="<<stage<<" visible="<<item.visible<<" disabled="<<item.disabled<<" rect="<<r[0]<<","<<r[1]<<","<<r[2]<<","<<r[3]<<"\n";Check(item.visible && !item.disabled && r[0]>=0 && r[1]>=0 && r[2]<=960 && r[3]<=640,"native coin action reachable");int x{},y{};glfwGetWindowPos(host.Window(),&x,&y);Check(motion(display,-1,x+int((r[0]+r[2])/2),y+int((r[1]+r[3])/2),0),"native coin pointer");Check(button(display,native_button,down,0),"native coin click");XSync(display,False);}
    void Capture(const platform::NativeFrame& f,const char* name){std::ofstream file(out/(std::string(name)+".ppm"),std::ios::binary);file<<"P6\n"<<f.framebuffer_width<<' '<<f.framebuffer_height<<"\n255\n";for(int y=f.framebuffer_height-1;y>=0;--y)for(int x=0;x<f.framebuffer_width;++x)file.write(reinterpret_cast<const char*>(f.rgba.data()+(size_t(y)*f.framebuffer_width+x)*4),3);Check(bool(file),"coin framebuffer retained");Check(state.presentation.Tree().Validate() && !state.presentation.Tree().overflow,"coin semantics valid and bounded");std::ofstream(out/(std::string(name)+".semantics.txt"))<<state.presentation.Snapshot();}
    void Release(unsigned native_button=1){Check(button(display,native_button,False,0),"native release");XSync(display,False);}
    void Frame(platform::NativeHost& host,const platform::NativeFrame& f) override {
        auto* wallet=state.documents.Find(1);if(!wallet)return;
        const auto after=[&](int n=3){return int(f.rendered_frames)>base+n;};
        const auto press=[&](const char* key){Click(host,facts.coin.at(key),true);base=int(f.rendered_frames);};
        if(stage==0){if(f.rendered_frames<4)return;Key(XK_Control_L,true);Key(XK_5,true);base=int(f.rendered_frames);stage=1;return;}
        if(stage==1 && after(0)){Key(XK_5,false);Key(XK_Control_L,false);stage=2;return;}
        if(stage==2){const auto history=a::HistoryForDocument(*wallet,requests.refresh,{});if(!history || !history->chain_current || !history->ledger->Complete() || !state.coins.contains(1) || !state.coins.at(1).inventory || facts.coin_order.size()<4)return;auto& inventory=*state.coins.at(1).inventory;auto totals=inventory.Summary({});Check(f.width==960 && f.height==640 && f.effective_scale==1.5F && !f.gl_error && f.font_texture,"actual native coin controls960x640/150 percent");Check(totals.total && totals.total->sats()==expected && totals.eligible && totals.eligible->sats()>0,"actual totals and acknowledged eligible policy");Capture(f,"coin-controls-start");press("next-group");stage=3;return;}
        if(stage==3 && after(0)){Release();stage=4;base=int(f.rendered_frames);return;}
        if(stage==4 && after()){press("toggle-group");stage=5;return;}
        if(stage==5 && after(0)){Release();stage=6;base=int(f.rendered_frames);return;}
        if(stage==6 && after()){Check(wallet->coins.Selection().size()==1,"native exact first group selection");keys={*wallet->coins.Selection().begin()};Check(state.coins.at(1).inventory->Rows().at(keys[0]).eligible==true,"chosen actual output locally eligible");Click(host,facts.coin.at("row-"+keys[0]),true,3);stage=7;base=int(f.rendered_frames);return;}
        if(stage==7 && after(0)){Release(3);stage=8;base=int(f.rendered_frames);return;}
        if(stage==8 && after()){Check(facts.coin.contains("freeze"),"actual native outpoint context opens");Capture(f,"coin-context-actions");press("freeze");stage=9;return;}
        if(stage==9 && after(0)){Release();stage=10;base=int(f.rendered_frames);return;}
        if(stage==10 && after()){Check(state.coins.at(1).inventory->Rows().at(keys[0]).eligible==false,"actual local freeze acknowledged/excluded");auto saved=requests.recovery->HistoryMetadata(a::HistoryMetadataScope(*wallet->binding));Check(saved && saved.value->freezes.size()==1 && saved.value->freezes[0].key==keys[0],"actual scoped durable output freeze record");Capture(f,"coin-context-frozen");press("unfreeze");stage=11;return;}
        if(stage==11 && after(0)){Release();stage=12;base=int(f.rendered_frames);return;}
        if(stage==12 && after()){Check(state.coins.at(1).inventory->Rows().at(keys[0]).eligible==true,"actual unfreeze acknowledged");Key(XK_Escape,true);stage=13;base=int(f.rendered_frames);return;}
        if(stage==13 && after(0)){Key(XK_Escape,false);stage=14;base=int(f.rendered_frames);return;}
        if(stage==14 && after()){press("next-group");stage=15;return;}
        if(stage==15 && after(0)){Release();stage=16;base=int(f.rendered_frames);return;}
        if(stage==16 && after()){press("toggle-group");stage=17;return;}
        if(stage==17 && after(0)){Release();stage=18;base=int(f.rendered_frames);return;}
        if(stage==18 && after()){selected=wallet->coins.Selection();Check(selected.size()==2,"actual two exact chart/table selections");press("send-selected");stage=19;return;}
        if(stage==19 && after(0)){Release();stage=20;base=int(f.rendered_frames);return;}
        if(stage==20 && after()){draft=state.documents.ActiveId();const auto* d=state.documents.Find(draft);Check(draft!=1 && d && d->coin_draft && d->coin_draft->inputs.size()==2,"actual typed pinned draft document");for(const auto& p:d->coin_draft->inputs)Check(selected.contains(a::CoinKey(p.outpoint)),"every selected identity transferred exactly");Check(!state.coin_controls.Owner(draft),"pinning alone confers no reservation");Capture(f,"send-pinned-coins");press("validate-pins");stage=21;return;}
        if(stage==21 && after(0)){Release();stage=22;base=int(f.rendered_frames);return;}
        if(stage==22){if(!state.coin_controls.Owner(draft))return;Check(state.coin_controls.DraftStatus(draft).find("Funding service unavailable")!=std::string::npos,"real fresh preflight ends at truthful unavailable funding seam");Capture(f,"pinned-owned-reservation");press("release-pins");stage=23;return;}
        if(stage==23 && after(0)){Release();stage=24;base=int(f.rendered_frames);return;}
        if(stage==24 && after()){Check(!state.coin_controls.Owner(draft),"actual owned release, no daemon unlock");const auto* d=state.documents.Find(draft);Check(d && d->coin_draft && d->selected_coins.size()==2,"release retains both exact public pins");std::ofstream marker(out/"external-conditions.json");marker<<"{\"genesis\":"<<rpc::Quote(d->coin_draft->wallet.network.genesis.hex())<<",\"wallet\":"<<rpc::Quote(d->coin_draft->wallet.DaemonWallet())<<",\"pins\":[";for(size_t n=0;n<d->coin_draft->inputs.size();++n){const auto& p=d->coin_draft->inputs[n];Check(p.value && p.value->sats()>10000,"owned controller input has exact public value");if(n)marker<<',';marker<<"{\"txid\":"<<rpc::Quote(p.outpoint.txid.hex())<<",\"vout\":"<<p.outpoint.index<<",\"satoshis\":"<<p.value->sats()<<'}';}marker<<"]}";marker.close();Check(bool(marker),"owned external-condition setup marker retained");press("validate-pins");stage=25;return;}
        if(stage==25 && after(0)){Release();stage=26;base=int(f.rendered_frames);return;}
        if(stage==26){const auto* d=state.documents.Find(draft);if(!d || !d->coin_draft || d->coin_draft->inputs[0].current_reason.find("external daemon lock")==std::string::npos || d->coin_draft->inputs[1].current_reason.find("absent")==std::string::npos)return;Check(!state.coin_controls.Owner(draft) && state.coin_controls.DraftStatus(draft).find("denied")!=std::string::npos,"actual external lock and spent-between-selection/preflight deny ownership/funding");Check(d->selected_coins.size()==2,"actual denied pins not dropped or substituted");for(const auto& p:d->selected_coins)Check(selected.contains(a::CoinKey(p)),"same exact denied outpoints retained");Capture(f,"pinned-newly-unavailable");press("show-coins");stage=27;return;}
        if(stage==27 && after(0)){Release();stage=28;base=int(f.rendered_frames);return;}
        if(stage==28 && after()){Check(state.documents.ActiveId()==1 && wallet->coins.Selection()==selected,"return preserves selected locked/spent identities");Key(XK_Control_L,true);Key(XK_Shift_L,true);Key(XK_h,true);stage=29;base=int(f.rendered_frames);return;}
        if(stage==29 && after(0)){Key(XK_h,false);Key(XK_Shift_L,false);Key(XK_Control_L,false);stage=30;base=int(f.rendered_frames);return;}
        if(stage==30 && after()){Check(state.privacy.hidden && !facts.coin.at("clear-selection").disabled && state.presentation.ChartSamples().empty(),"Clear remains available for hidden/unavailable exact selection");Capture(f,"clear-pinned-selection-hidden");press("clear-selection");stage=31;return;}
        if(stage==31 && after(0)){Release();stage=32;base=int(f.rendered_frames);return;}
        if(stage==32 && after()){Check(wallet->coins.Selection().empty() && state.documents.Find(draft)->selected_coins.size()==2 && !state.coin_controls.Owner(draft),"Clear selection works independently of retained public draft pins");requests.connection.SetOffline(true);requests.refresh.Unbind();stage=33;return;}
        if(stage==33 && !requests.refresh.Busy()){done=true;host.RequestClose();}
    }
    void Key(KeySym sym,bool down){Check(key(display,XKeysymToKeycode(display,sym),down,0),"native coin key");XSync(display,False);}
    void Teardown(const platform::NativeTeardown& t) override{cleaned=t.renderer_cleared && t.platform_cleared && t.textures_released && t.imgui_cleared && t.context_cleared;Check(cleaned,"native coin resources settled");}
};
